  "Use the higher timeframe for direction, the middle one for the setup and the lower one for timing, and only act when they line up.": "Utilice el plazo más alto para la dirección, el medio para la configuración y el inferior para el tiempo, y sólo actuar cuando se alinean.",
  "Breakouts, fakeouts and liquidity": "Breakouts, fakeouts and liquidity",
  "Why levels break, why so many first breaks fail, and where the stop orders sit that fuel both. Trade the confirmed break, fade the trap, or wait for the retest.": "Por qué los niveles se rompen, por qué tantos primeros descansos fallan, y donde las órdenes de parada se sientan que alimentan ambos. Cambiar el descanso confirmado, desvanecer la trampa, o esperar la prueba.",
  "Game · Predict · 7 min": "Juego · Predicción · 7 min",
  "Lesson · 15 min": "Lección · 15 min",
  "Stack independent reasons for a trade, choose the moment to act, then size the position so one loss never hurts much. Stops, targets, R-multiples and expectancy.": "Rastrear razones independientes para un trading, elegir el momento para actuar, luego tamaño la posición por lo que una pérdida nunca duele mucho. Paradas, objetivos, R-multiples y esperanza.",
  "Game · Calculate · 8 min": "Juego · Calcular · 8 min",
  "Trading psychology and your plan": "Trading de psicología y su plan",
  "Fear, greed, revenge trading and tilt: the mistakes that cost more than any bad setup. Write a trading plan and a checklist you will actually follow.": "El miedo, la codicia, el trading de venganza y la inclinación: los errores que cuestan más que cualquier mal montaje. Escribe un plan comercial y una lista de verificación que realmente seguirás.",
