  "Head and shoulders": "Cabeza y hombros",
  "Sim": "Sim",
  "Neckline": "Neckline",
  "Three peaks at the end of an uptrend: a left shoulder, a higher head, and a right shoulder at about the height of the left one. The neckline joins the two lows between them.": "Tres picos al final de una subida: un hombro izquierdo, una cabeza superior y un hombro derecho alrededor de la altura del izquierdo. El escote se une a los dos bajos entre ellos.",
  "reversal · chart pattern": "reversal · patrón de gráfico",
  "Inverse head and shoulders": "Cabeza y hombros inversos",
  "Three troughs at the end of a downtrend: a left shoulder, a lower head, and a right shoulder at about the depth of the left one. The neckline joins the two highs between them.": "Tres tropiezos al final de una contrabajo: un hombro izquierdo, una cabeza inferior y un hombro derecho alrededor de la profundidad de la izquierda. El escote se une a los dos altos entre ellos.",
  "Double top": "Doble superior",
  "Two peaks at about the same price with a trough between them, shaped like an 'M'. The neckline is the low between the peaks.": "Dos picos al mismo precio con un trough entre ellos, con forma de 'M'. El escote es el bajo entre los picos.",
  "Double bottom": "Doble fondo",
  "Two troughs at about the same price with a peak between them, shaped like a 'W'. The neckline is the high between the troughs.": "Dos tropiezos al mismo precio con un pico entre ellos, con forma de 'W'. El escote es el alto entre los pantalones.",
  "Triple top": "Triple superior",
  "Three peaks at about the same level with two troughs between them. The neckline (support) runs through the troughs.": "Tres picos al mismo nivel con dos troughs entre ellos. El escote (apoyo) corre a través de los pantalones.",
  "Triple bottom": "Fondo triple",
  "Three troughs at about the same level with two peaks between them. The neckline (resistance) runs through the peaks.": "Tres troughs en aproximadamente el mismo nivel con dos picos entre ellos. El escote (resistencia) atraviesa los picos.",
  "Rising wedge": "Wedge creciente",
  "Price climbs between two rising trend lines that converge, with the lower line steeper than the upper one. It usually breaks down.": "Los precios suben entre dos líneas de tendencia que convergen, con la línea inferior más empinada que la superior. Normalmente se descompone.",
  "Falling wedge": "Cayendo la cuña",
  "Price falls between two descending trend lines that converge, with the upper line steeper than the lower one. It usually breaks out upward.": "El precio cae entre dos líneas de tendencia descendente que convergen, con la línea superior más empinada que la inferior. Normalmente se rompe hacia arriba.",
  "Ascending triangle": "Triángulo ascendente",
  "A flat resistance line on top and rising lows underneath. It most often breaks upward, continuing an uptrend.": "Una línea de resistencia plana encima y baja subiendo por debajo. Con más frecuencia se rompe hacia arriba, continuando con una tendencia ascendente.",
  "continuation · chart pattern": "continuación · patrón gráfico",
  "Descending triangle": "Triángulo descendente",
  "A flat support line underneath and falling highs above it. It most often breaks downward, continuing a downtrend.": "Una línea de soporte plana por debajo y cayendo por encima de ella. Con más frecuencia se descompone hacia abajo, continuando con una baja tendencia.",
  "Symmetrical triangle": "triángulo simétrico",
  "Lower highs and higher lows squeeze price between two converging trend lines. It usually breaks in the direction of the trend that came before it.": "Los altos más bajos y bajos más altos presionan precio entre dos líneas de tendencia convergentes. Por lo general se rompe en la dirección de la tendencia que llegó antes.",
  "Bull flag": "Bandera de toros",
  "A sharp rally (the flagpole) followed by a small, orderly pullback inside a slightly downward-sloping channel (the flag).": "Un rallye afilado (el asta de bandera) seguido por una pequeña y ordenada tirada dentro de un canal ligeramente hacia abajo (la bandera).",
  "Bear flag": "Bandera de oso",
  "A sharp drop (the flagpole) followed by a small, orderly bounce inside a slightly upward-sloping channel (the flag).": "Una gota afilada (el asta de bandera) seguida por un pequeño y ordenado rebote dentro de un canal ligeramente ascendente (la bandera).",
  "Cup and handle": "Copa y mango",
  "A rounded 'U'-shaped base (the cup) followed by a short, shallow pullback (the handle) just below the cup's rim.": "Una base redondeada en forma de 'U' (la taza) seguido por un corto, poco profundo (la manija) justo debajo del borde de la taza.",
  "Rounding bottom": "Fondo redondeado",
  "A long, gradual 'saucer'-shaped bottom where a downtrend slowly flattens out and turns back up.": "Un fondo largo y gradual en forma de 'saucer' donde un downtrend lentamente se aplana y vuelve hacia arriba.",
  "Rounding top": "Redondeo superior",
  "A long, gradual 'dome'-shaped top where an uptrend slowly flattens out and turns back down.": "Una larga y gradual parte superior en forma de 'dome' donde un uptrend lentamente se aplana y retrocede.",
  "Bull pennant": "Colgante de bala",
  "A sharp rally (the flagpole) followed by a short, converging triangle of lower highs and higher lows (the pennant).": "Un rallye afilado (el asta de bandera) seguido de un triángulo corto, convergente de alturas inferiores y bajos superiores (el colgante).",
  "Bear pennant": "Colgante de oso",
  "A sharp drop (the flagpole) followed by a short, converging triangle of higher lows and lower highs (the pennant).": "Una gota afilada (el asta de bandera) seguida de un triángulo corto, convergente de bajos superiores y altos inferiores (el colgante).",
  "Bull rectangle": "Bala rectángulo",
  "After an uptrend, price consolidates between flat support and flat resistance (a trading range), then breaks upward.": "Después de un ascenso, el precio se consolida entre el soporte plano y la resistencia plana (un rango de trading), luego se rompe hacia arriba.",
  "Bear rectangle": "Rectángulo de oso",
  "After a downtrend, price consolidates between flat support and flat resistance (a trading range), then breaks downward.": "Después de un descenso, el precio se consolida entre el soporte plano y la resistencia plana (una gama de trading), luego se descompone hacia abajo.",
