  "Volume as participation: confirming breakouts, spotting thin traps, and reading climax vs dry-up.": "Volumen como participación: confirmando rupturas, detectando trampas delgadas y leyendo climax vs secado.",
  "· Fuel behind the move": "· Combustible detrás del movimiento",
