  "9 steps": "9 pasos",
  "Every fill has two sides. Learn what a market is, who is on the other side, how bids and asks form a spread, and when to use market, limit and stop orders — with visuals that play out as you read.": "Cada relleno tiene dos lados. Aprenda qué es un mercado, que está en el otro lado, cómo las ofertas y las preguntas forman una extensión, y cuándo utilizar el mercado, limitar y detener las órdenes, con visuales que juegan como usted lee.",
  "Step 1 of 9": "Paso 1 de 9",
  "· What a market is (and why it exists)": "· Qué es un mercado (y por qué existe)",
  "What a market is (and why it exists)": "Qué mercado es (y por qué existe)",
  "Who is on the other side?": "¿Quién está del otro lado?",
  "The bid–ask spread": "La oferta se extendió",
  "Bid, ask and a market fill": "Bid, pide y llena el mercado",
  "Market orders vs limit orders": "Órdenes de mercado vs límite",
  "Stops, slippage, and honest caveats": "Para, deslizamiento, y cavernas honestas",
  "Quick check: pullback buy": "Cheque rápido: compra de devolución",
  "Quick check: protective exit": "Control rápido: salida protectora",
  "Quick check: the spread": "Cheque rápido: la extensión",
  "A market is a meeting place. It exists so strangers can agree on a price without knowing each other.": "Un mercado es un lugar de encuentro. Existe tan extraños pueden estar de acuerdo en un precio sin conocerse.",
  "Stock exchanges, futures pits, and crypto venues all do the same job: match someone who wants to buy with someone who wants to sell.": "Bolsas de valores, futuros pozos y lugares de cripto todos hacen el mismo trabajo: coinciden con alguien que quiere comprar con alguien que quiere vender.",
  "Your": "Tu",
  "broker": "broker",
  "is the doorway (the app or desk that routes your order). The": "es la puerta (la aplicación o escritorio que recorre su pedido). El",
  "exchange": "cambio",
  "(or liquidity venue) is where resting orders live in the book. On an exchange you trade against another participant, not the broker (retail stock orders are often filled by a wholesale market maker). With CFDs, spread bets, most retail FX and binary options, the broker itself is usually on the other side of your trade.": "(o lugar de liquidez) es donde las órdenes de descanso viven en el libro. En un intercambio comercial contra otro participante, no el corredor (las órdenes de acciones minoristas son a menudo llenadas por un fabricante de mercado mayorista). Con CFDs, apuestas de propagación, la mayoría de FX minorista y opciones binarias, el corredor en sí suele estar en el otro lado de su trading.",
  "Exchange": "Cambio",
  "Buyers": "Compradores",
  "Sellers": "Vendedores",
  "A trade prints when someone crosses — a buyer lifts an ask, or a seller hits a bid.": "Una impresión comercial cuando alguien cruza — un comprador levanta una pregunta, o un vendedor golpea una oferta.",
  "Markets concentrate buyers and sellers so prices can be discovered continuously.": "Los mercados concentran compradores y vendedores para que los precios puedan ser descubiertos continuamente.",
  "Broker = access; exchange/venue = matching and the order book.": "Broker = acceso; intercambio/venue = igualación y el libro de órdenes.",
  "Without the other side, there is no trade — only a wish.": "Sin el otro lado, no hay trading, sólo un deseo.",
  "Step 1: What a market is (and why it exists)": "Paso 1: Qué es un mercado (y por qué existe)",
  "Step 2: Who is on the other side?": "Paso 2: ¿Quién está al otro lado?",
