  "Price makes a swing high. Momentum (e.g. RSI) is strong.": "El precio hace un swing alto. Momentum (por ejemplo RSI) es fuerte.",
  "High A": "High A",
  "Higher high, weaker thrust.": "Más alto, más débil.",
  "Price makes a higher high while momentum fails to confirm — classic bearish divergence setup.": "El precio hace que un alto más alto mientras el impulso no confirma — la clásica divergencia de los osos.",
  "High B": "High B",
  "Divergence can persist in strong trends. Treat it as a warning, wait for structure to break.": "La diversidad puede persistir en tendencias fuertes. Tratarlo como una advertencia, espera a que la estructura se rompa.",
  "MA 10": "MA 10",
  "MA 30": "MA 30",
  "Downtrend with oversold RSI condition": "Downtrend with oversold RSI condition",
  "Still falling": "Sigue cayendo",
