  "Strong downtrend, RSI at 25, no reversal pattern yet. Best action?": "Strong downtrend, RSI a los 25, sin patrón de inversión todavía. ¿La mejor acción?",
  "Wait — oversold is a condition, not a buy signal": "Espera — oversold es una condición, no una señal de compra",
  "Buy immediately, it must bounce": "Comprar inmediatamente, debe rebotar",
  "Short with no stop": "Corto sin parar",
