  ", measured target ": ", objetivo medido",
  "The breakout failed: trapped breakout traders exit and fuel the move back across the range.": "El desguace falló: los comerciantes desintegración atrapados salen y alimentan el movimiento de vuelta a través de la gama.",
  "Follow-through toward the measured move. Not every pattern gets there — manage risk.": "Seguimiento hacia el movimiento medido. No cada patrón llega allí — gestionar el riesgo.",
  "This outcome failed — traps happen; the stop was there for a reason.": "Este resultado falló: ocurren trampas; la parada estaba allí por una razón.",
