  "Simulation unavailable: ": "Simulación no disponible:",
  "Press Play to walk through the setup, one step at a time.": "Pulse Jugar para caminar a través de la configuración, un paso a la vez.",
  "Play simulation": "simulación de juego",
  " Play": "Jugar",
  "Replay from start": "Replay desde el principio",
  " Replay": "Replay",
  " animated walk-through": "Paseo animado",
  " simulation": "simulación",
  "Watch the setup form, one candle at a time.": "Mira la forma de configuración, una vela a la vez.",
  " Pause": "Pausa",
  "Pause simulation": "simulación de pausa",
  " walk-through complete. Hit Replay to watch again.": "paseo completo. Hit Replay para volver a ver.",
  "in any context": "en cualquier contexto",
  "after a ": "después de una",
  ", at the extreme of the move": ", en el extremo del movimiento",
  "Over 50 candles: regression rise ≥ 5 ATR with R² ≥ 0.5, the last two swing highs and lows both higher, EMA 20 above a rising EMA 50 and price above EMA 50. Reported once when the trend is first confirmed.": "Más de 50 velas: subida de regresión ≥ 5 ATR con R2 ≥ 0.5, los últimos dos altos oscilantes y bajos ambos más alto, EMA 20 por encima de un aumento de EMA 50 y precio por encima de EMA 50. Reportado una vez cuando la tendencia se confirma por primera vez.",
  "Mirror of the uptrend: fall ≥ 5 ATR, R² ≥ 0.5, lower highs and lower lows, EMA 20 below a falling EMA 50, price below EMA 50.": "Espejo de la tendencia ascendente: caída ≥ 5 ATR, R2 ≥ 0.5, bajos altos y bajos bajos, EMA 20 debajo de una caída EMA 50, precio por debajo de EMA 50.",
  "Over 40 candles: high-to-low height 3–8 ATR, regression drift ≤ 1.5 ATR, at least two swing highs near the top and two swing lows near the bottom (within a quarter of the height), and price still inside.": "Más de 40 velas: altura alta a baja 3-8 ATR, deriva de regresión ≤ 1,5 ATR, al menos dos alturas de oscilación cerca de la parte superior y dos bajos de oscilación cerca de la parte inferior (dentro de una cuarta parte de la altura), y precio todavía dentro.",
  "Mirror of the support bounce at a resistance made by ≥ 2 earlier swing highs.": "El espejo del soporte rebota a una resistencia hecha por ≥ 2 altos oscilantes anteriores.",
  "Breakout up": "Breakout",
  "The first close ≥ 0.2 ATR above a resistance made by ≥ 2 swing highs (≥ 2 ATR zigzag swings within 0.5 ATR) that held for ≥ 10 candles, on a candle with a body ≥ 0.4 ATR closing in its upper half.": "El primer cierre ≥ 0,2 ATR por encima de una resistencia hecha por ≥ 2 alturas de oscilación (≥ 2 oscilaciones ATR zigzag dentro de 0,5 ATR) que retenían por ≥ 10 velas, en una vela con un cuerpo ≥ 0,4 ATR cierre en su mitad superior.",
  "Breakout down": "Desintegración",
  "Mirror of the breakout up through a support made by ≥ 2 swing lows.": "Espejo de la ruptura a través de un soporte realizado por ≥ 2 bajos de oscilación.",
  "Failed breakout up": "Failed breakout up",
  "The first close above a ≥ 2-touch resistance, then within 15 candles (without running more than 5 ATR above it) a close back ≥ 0.25 ATR below it: the breakout trapped buyers.": "El primer cierre por encima de una resistencia ≥ 2-touch, luego dentro de 15 velas (sin correr más de 5 ATR por encima de él) una espalda cercana ≥ 0.25 ATR por debajo: el despegue de compradores atrapados.",
  "Failed breakout down": "Desaparecido",
  "Mirror of the failed breakout up at a support.": "Espejo de la ruptura fallida en un apoyo.",
  "A new swing low vs the lowest swing low 5–40 candles earlier, with a ≥ 1.5 ATR bounce between them: price makes a lower low (≥ 0.25 ATR lower) while RSI 14 makes a higher low (≥ 4 points higher) and the first RSI low is below 35. Decided 3 candles after the second low (when it is confirmed as a swing).": "Un nuevo swing bajo vs el swing más bajo 5–40 velas antes, con un rebote ≥ 1,5 ATR entre ellos: precio hace un bajo menor (≥ 0.25 ATR inferior) mientras que RSI 14 hace un bajo más alto (≥ 4 puntos más alto) y el primer bajo RSI es inferior a 35. Decidió 3 velas después del segundo bajo (cuando se confirma como un columpio).",
  "Mirror: price higher high, RSI lower high (≥ 4 points), first RSI high above 65.": "Espejo: precio alto alto, RSI inferior alto (≥ 4 puntos), primero RSI alto sobre 65.",
  "A clean impulse of ≥ 3 ATR between two zigzag swings (mostly one-way: net move ≥ 0.55 × the candle-to-candle path), a pullback of ≥ 2 candles that ends between the 0.382 and 0.786 retracement (never closing beyond 0.786), and a candle in the impulse direction (body ≥ 0.3 ATR) that closes beyond the pullback candle within 3 candles of its extreme. meta.ratio is the retracement.": "Un impulso limpio de ≥ 3 ATR entre dos oscilaciones de zigzag (principalmente una vía: movimiento neto ≥ 0.55 × el camino de vela a vela), una retroceso de ≥ 2 velas que termina entre el 0,32 y 0,786 retracemento (nunca cerrando más allá de 0,76), y una vela en la dirección de impulso (cuerpo ≥ 0,3 ATR) que se cierra más allá de la vela. meta.ratio es el retracemento.",
  "Two zigzag peaks 8–80 candles apart within max(0.6 ATR, 25% of the height) of each other and clearly above everything between them, the lowest low between them ≥ 2.5 ATR below (the neckline), a rise into the first peak, and the first close below the trough (neckline) within 25 candles of the second peak.": "Dos picos de zigzag 8–80 velas separadas en máx(0.6 ATR, 25% de la altura) entre sí y claramente por encima de todo entre ellos, el bajo más bajo entre ellos ≥ 2,5 ATR debajo (el escote), un aumento en el primer pico, y el primer cierre debajo de la trucha (neckline) dentro de 25 velas del segundo pico.",
  "Mirror of the double top: two matching troughs, then the first close above the peak between them.": "Espejo de la doble parte superior: dos tropiezos iguales, luego el primero cerca del pico entre ellos.",
  "A zigzag head that is the highest point of the pattern, ≥ 0.8 ATR above both shoulders (each the high of its side and ≥ 1 ATR above the neckline), shoulders within 35% of the head height of each other, a neckline (through the two troughs) whose troughs differ by ≤ 50% of the head height, a rise into the left shoulder, and within 25 candles of the right shoulder the first close ≥ 0.1 ATR below both the neckline and every close of the trough before the right shoulder.": "Un cabezal zigzag que es el punto más alto del patrón, ≥ 0.8 ATR sobre ambos hombros (cada uno de los más altos de su lado y ≥ 1 ATR sobre el escote), los hombros dentro del 35% de la altura de la cabeza uno del otro, un escote (a través de los dos tropiezos) cuyos tropiezos difieren en ≤ 50% de la altura de la cabeza, un aumento en el hombro izquierdo, y dentro de 25 velas ≥ 0",
  "Mirror of head and shoulders below a neckline through the two peaks.": "Espejo de cabeza y hombros debajo de un escote a través de los dos picos.",
  "A pole rising ≥ 5 ATR in ≤ 20 candles (≥ 0.3 ATR per candle, net move ≥ 0.4 × the path), then a flag of 4–35 candles (at most 2.2 × the pole) that drifts sideways or gently down (closes falling at ≤ 0.5 × the pole’s pace), retraces ≤ 50% of the pole and more slowly than the pole rose, and is quieter (average candle range ≤ 0.85 × the pole’s), and the first close ≥ 0.1 ATR above the flag’s upper line (fitted to the flag’s own highs, never rising, touching the highest).": "Un poste subiendo ≥ 5 ATR en ≤ 20 velas (≥ 0.3 ATR por vela, movimiento neto ≥ 0.4 × el camino), luego una bandera de 4–35 velas (en la mayoría 2.2 × el poste) que deriva lateralmente o suavemente hacia abajo (cerros cayendo en ≤ 0.5 × el paso del polo), retraces ≤ 50% del poste y más lentamente que el polo superior ≥ 0",
  "Mirror of the bull flag after a falling pole.": "Espejo de la bandera del toro después de un poste caído.",
